const item = $('Execute Workflow Trigger').first().json;
const platforms = item.platforms || ['LinkedIn','X','Instagram','Facebook','Newsletter','TikTok'];

const system = 'أنت خبير إعادة استخدام المحتوى. حوّل المقال إلى محتوى لكل منصة دون نسخ حرفي. أعد JSON صالحاً فقط.';
const user = 'المقال: ' + JSON.stringify(item.draft) +
  '\nالمنصات: ' + JSON.stringify(platforms) +
  '\nأعد مصفوفة: [{"platform":"...","format":"post|thread|story|video_script|carousel|newsletter","copy":"...","hashtags":["..."],"best_time":"HH:MM","media_ref":null,"char_count":0}]. ' +
  '\nقواعد: LinkedIn احترافي ≤3000 حرف، X ≤280، Instagram 5-8 هاشتاقات، TikTok سكربت ≤60 ثانية، Newsletter ملخص + 3 نقاط + CTA.';

return [{ json: { task_type: 'repurpose', payload: { system, user } } }];

const items = $input.all().flatMap(i => {
  const arr = i.json.platforms || i.json.repurposed || i.json;
  if (Array.isArray(arr)) return arr;
  return [arr];
});

const limits = { X: 280, 'X (Twitter)': 280, LinkedIn: 3000, Instagram: 2200 };
const validated = items.map((p, idx) => {
  const limit = limits[p.platform] || 4000;
  const copy = p.copy || '';
  const trimmed = copy.length > limit ? copy.slice(0, limit) : copy;
  return {
    json: {
      item_id: 'R-' + ($('Execute Workflow Trigger').first().json.content_id || 'NA') + '-' + idx,
      content_id: $('Execute Workflow Trigger').first().json.content_id,
      platform: p.platform,
      format: p.format || 'post',
      copy: trimmed,
      hashtags: Array.isArray(p.hashtags) ? p.hashtags.slice(0, 8) : [],
      best_time: p.best_time || '10:00',
      media_ref: p.media_ref || null,
      char_count: trimmed.length,
      truncated: trimmed.length < copy.length
    }
  };
});
return validated;
